import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

async function syncCatalog() {
  'use server'

  void fetch('https://erp.internal/sync-catalog', { method: 'POST' })

  revalidateTag('products')
}

export default async function CatalogPage() {
  const products = await getProducts()

  return (
    <main style={{ fontFamily: 'system-ui', padding: 24, maxWidth: 720 }}>
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <h1 style={{ margin: 0 }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>

      <p style={{ color: '#666' }}>
        Catalog data is cached and tagged as <code>products</code>. Triggering
        a sync invalidates the tag so every dependent view revalidates on its
        next request.
      </p>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 16 }}>
        <thead>
          <tr>
            <th
              style={{
                textAlign: 'left',
                borderBottom: '1px solid #ddd',
                padding: 8,
              }}
            >
              ID
            </th>
            <th
              style={{
                textAlign: 'left',
                borderBottom: '1px solid #ddd',
                padding: 8,
              }}
            >
              Name
            </th>
            <th
              style={{
                textAlign: 'right',
                borderBottom: '1px solid #ddd',
                padding: 8,
              }}
            >
              Price
            </th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>
                {product.id}
              </td>
              <td style={{ borderBottom: '1px solid #eee', padding: 8 }}>
                {product.name}
              </td>
              <td
                style={{
                  borderBottom: '1px solid #eee',
                  padding: 8,
                  textAlign: 'right',
                }}
              >
                ${product.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

